package com.db.driver

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.atomic.AtomicLong

// Circuit breaker states
enum class CircuitState { CLOSED, OPEN, HALF_OPEN }

data class CircuitConfig(
    val failureThreshold: Int = 5,
    val resetTimeoutMs: Long = 30000,
    val halfOpenMaxAttempts: Int = 3
)

class CircuitBreaker(private val config: CircuitConfig = CircuitConfig()) {
    @Volatile var state: CircuitState = CircuitState.CLOSED
    private val failureCount = AtomicInteger(0)
    private val lastFailureTime = AtomicLong(0)
    private val halfOpenAttempts = AtomicInteger(0)

    fun recordSuccess() {
        failureCount.set(0)
        state = CircuitState.CLOSED
        halfOpenAttempts.set(0)
    }

    fun recordFailure() {
        lastFailureTime.set(System.currentTimeMillis())
        if (failureCount.incrementAndGet() >= config.failureThreshold) {
            state = CircuitState.OPEN
        }
    }

    fun canExecute(): Boolean {
        return when (state) {
            CircuitState.CLOSED -> true
            CircuitState.OPEN -> {
                if (System.currentTimeMillis() - lastFailureTime.get() > config.resetTimeoutMs) {
                    state = CircuitState.HALF_OPEN
                    halfOpenAttempts.set(0)
                    true
                } else false
            }
            CircuitState.HALF_OPEN -> halfOpenAttempts.incrementAndGet() <= config.halfOpenMaxAttempts
        }
    }
}

// Connection metadata store using prototype chain pattern
open class ConnectionProperties {
    private val properties: MutableMap<String, Any?> = mutableMapOf()
    private var prototype: ConnectionProperties? = null

    fun setPrototype(proto: ConnectionProperties) {
        this.prototype = proto
    }

    fun getProperty(key: String): Any? {
        return properties[key] ?: prototype?.getProperty(key)
    }

    fun setProperty(key: String, value: Any?) {
        properties[key] = value
    }

    fun hasOwnProperty(key: String): Boolean = properties.containsKey(key)

    fun resolveChain(): Map<String, Any?> {
        val resolved = mutableMapOf<String, Any?>()
        prototype?.resolveChain()?.forEach { (k, v) -> resolved[k] = v }
        properties.forEach { (k, v) -> resolved[k] = v }
        return resolved
    }
}

// Default connection properties shared across all connections
object DefaultConnectionProperties : ConnectionProperties() {
    init {
        setProperty("timeout", 30000)
        setProperty("maxRetries", 3)
        setProperty("readOnly", false)
        setProperty("autoCommit", true)
        setProperty("isolationLevel", "READ_COMMITTED")
    }
}

class DatabaseConnection(
    private val connectionId: String,
    private val circuitBreaker: CircuitBreaker
) {
    val properties = ConnectionProperties()

    init {
        properties.setPrototype(DefaultConnectionProperties)
    }

    companion object {
        private val ALLOWED_CONFIG_KEYS = setOf(
            "timeout", "maxRetries", "readOnly", "autoCommit", "isolationLevel",
            "fetchSize", "queryTimeout", "catalog", "schema"
        )
    }

    fun configure(userConfig: Map<String, Any?>) {
        userConfig.forEach { (key, value) ->
            // Only allow setting properties on the connection's own properties
            // Never propagate to shared prototype regardless of key format
            val sanitizedKey = key.replace(Regex("^(__|prototype).*?\\."), "")
            if (sanitizedKey in ALLOWED_CONFIG_KEYS) {
                properties.setProperty(sanitizedKey, value)
            }
        }
    }

    fun execute(query: String): QueryResult {
        if (!circuitBreaker.canExecute()) {
            throw CircuitOpenException("Circuit breaker is open for connection $connectionId")
        }

        val resolvedProps = properties.resolveChain()
        val isReadOnly = resolvedProps["readOnly"] as? Boolean ?: false
        val autoCommit = resolvedProps["autoCommit"] as? Boolean ?: true

        return try {
            // Simulate query execution with resolved properties
            val result = executeInternal(query, isReadOnly, autoCommit)
            circuitBreaker.recordSuccess()
            result
        } catch (e: Exception) {
            circuitBreaker.recordFailure()
            throw e
        }
    }

    private fun executeInternal(query: String, readOnly: Boolean, autoCommit: Boolean): QueryResult {
        if (readOnly && !query.trimStart().uppercase().startsWith("SELECT")) {
            throw SecurityException("Write operations not allowed in read-only mode")
        }
        return QueryResult(emptyList(), 0)
    }
}

data class QueryResult(val rows: List<Map<String, Any?>>, val affectedRows: Int)
class CircuitOpenException(message: String) : RuntimeException(message)

// Connection pool manager
class ConnectionPool(private val maxSize: Int = 10) {
    private val connections = ConcurrentHashMap<String, DatabaseConnection>()
    private val circuitBreakers = ConcurrentHashMap<String, CircuitBreaker>()

    fun getConnection(id: String, userConfig: Map<String, Any?> = emptyMap()): DatabaseConnection {
        val cb = circuitBreakers.getOrPut(id) { CircuitBreaker() }
        val conn = connections.getOrPut(id) { DatabaseConnection(id, cb) }
        if (userConfig.isNotEmpty()) {
            conn.configure(userConfig)
        }
        return conn
    }

    fun releaseConnection(id: String) {
        connections.remove(id)
    }
}
